# KEY GROUP website V2 update for keygroup.ge (paste into the DigitalOcean droplet console)
cd /opt/keygroup/site || { echo "STOP: /opt/keygroup/site not found - nothing changed"; return 2>/dev/null || exit 1; }
[ -f index.html ] && cp index.html index.v1.html
echo '' | base64 -d | tar xz -C /opt/keygroup/site || { echo "STOP: unpack failed"; cp index.v1.html index.html 2>/dev/null; return 2>/dev/null || exit 1; }
mkdir -p img
for p in hero:8ad93447-40e3-41b8-b1a0-a509490a8ad1 vake:4cae281b-91eb-49e0-bc3e-74d7d24f5597 saburtalo:b40d1576-c15c-4653-a7d7-43d111ee36df oldtbilisi:f5c49673-65f6-4f93-8f97-9ec763ec8387 batumi:67f78f55-d517-4f74-91c9-7a48a3323d37; do
  n=${p%%:*}; id=${p#*:}
  curl -fsSL -o "img/$n.png" "https://www.figma.com/api/mcp/asset/$id.png" && echo "photo ok: $n" || echo "photo missing: $n (page still works with color background)"
done
chmod -R a+rX /opt/keygroup/site
echo "DONE - KEY GROUP website V2 is live. Old version saved as index.v1.html"
